import {initLab} from './lab.js';
const $=id=>document.getElementById(id),music=$('music'),cosmos=$('cosmos'),sky=cosmos.getContext('2d');
let screen='home',elapsed=0,introTime=0,last=performance.now(),calm=matchMedia('(prefers-reduced-motion: reduce)').matches,musicWanted=false,analyser=null,audioContext=null,audioData=null,amplitude=0,skyW=innerWidth,skyH=innerHeight,hiddenAudio=false;
function hash(n){return ((Math.sin(n*127.1+311.7)*43758.5453)%1+1)%1;}
const stars=Array.from({length:160},(_,i)=>({x:hash(i*7.3),y:hash(i*11.9),r:.4+hash(i*3.1)*1.2,phase:hash(i)*6.28}));
function show(id){document.querySelectorAll('.screen').forEach(el=>el.classList.toggle('hidden',el.id!==id));screen=id;document.body.classList.toggle('in-lab',id==='lab');document.body.classList.toggle('cinema-mode',id==='intro');window.scrollTo({top:0,behavior:'instant'});}
function resizeSky(){skyW=innerWidth;skyH=innerHeight;const d=Math.min(devicePixelRatio||1,2);cosmos.width=skyW*d;cosmos.height=skyH*d;sky.setTransform(d,0,0,d,0,0);}
window.addEventListener('resize',resizeSky);resizeSky();
function ending(count){show('ending');$('ending-stats').textContent=`${count} / 18 DISCOVERIES · SEVEN ROOMS · INFINITE POSSIBILITIES`;}
const lab=initLab({show,onEnding:ending});
$('motion').setAttribute('aria-pressed',String(calm));document.body.classList.toggle('calm',calm);
$('motion').onclick=()=>{calm=!calm;document.body.classList.toggle('calm',calm);$('motion').setAttribute('aria-pressed',String(calm));};
function soundUI(){const playing=!music.paused;$('sound-label').textContent=playing?'ON':'OFF';$('sound').setAttribute('aria-label',playing?'Turn music off':'Turn music on');}
async function playMusic(){musicWanted=true;try{music.volume=.65;await music.play();if(!audioContext){const AC=window.AudioContext||window.webkitAudioContext;if(AC){audioContext=new AC();analyser=audioContext.createAnalyser();analyser.fftSize=128;audioData=new Uint8Array(analyser.frequencyBinCount);const source=audioContext.createMediaElementSource(music);source.connect(analyser);analyser.connect(audioContext.destination);}}if(audioContext?.state==='suspended')await audioContext.resume();}catch{musicWanted=false;}soundUI();}
$('sound').onclick=()=>{if(music.paused)playMusic();else{music.pause();musicWanted=false;soundUI();}};music.addEventListener('play',soundUI);music.addEventListener('pause',soundUI);music.addEventListener('error',()=>{$('sound-label').textContent='UNAVAILABLE';});
function beginIntro(){introTime=0;last=performance.now();show('intro');playMusic();}
$('begin').onclick=beginIntro;$('skip').onclick=()=>show('flower');$('accept').onclick=()=>{lab.atlas();show('atlas');};$('replay').onclick=()=>{lab.atlas();show('atlas');};$('replay-intro').onclick=()=>{music.currentTime=0;beginIntro();};
document.addEventListener('visibilitychange',()=>{if(document.hidden){hiddenAudio=!music.paused;if(hiddenAudio)music.pause();}else{last=performance.now();if(hiddenAudio&&musicWanted){hiddenAudio=false;playMusic();}}});
function circle(c,x,y,r,color){c.beginPath();c.arc(x,y,Math.max(0,r),0,Math.PI*2);if(color){c.fillStyle=color;c.fill();}else c.stroke();}
function line(c,points,color,width=1){c.beginPath();points.forEach((p,i)=>i?c.lineTo(...p):c.moveTo(...p));c.strokeStyle=color;c.lineWidth=width;c.stroke();}
function drawSky(){sky.clearRect(0,0,skyW,skyH);if(screen!=='intro')return;sky.fillStyle='#14111f';sky.fillRect(0,0,skyW,skyH);const t=calm?0:elapsed;for(const s of stars)circle(sky,s.x*skyW,s.y*skyH,s.r,`rgba(225,208,248,${.2+.45*(.5+.5*Math.sin(t*.5+s.phase))})`);drawMathematics(sky,skyW,skyH,t,introTime);}
function drawHeart(c,x,y,size,t,alpha=1){c.save();c.globalAlpha=alpha;for(let j=0;j<3;j++){const pts=[];for(let a=0;a<=Math.PI*2+.04;a+=.035){const k=size/18*(1+j*.045);pts.push([x+k*16*Math.sin(a)**3,y-k*(13*Math.cos(a)-5*Math.cos(2*a)-2*Math.cos(3*a)-Math.cos(4*a))]);}line(c,pts, j===0?'#f1afba':'#bca7dd',j===0?1.6:.6);}for(let i=0;i<12;i++){const a=t*.1+i*Math.PI/6,k=size/18;circle(c,x+k*16*Math.sin(a)**3,y-k*(13*Math.cos(a)-5*Math.cos(2*a)-2*Math.cos(3*a)-Math.cos(4*a)),2,'#fce6dc');}c.restore();}
function drawMathematics(c,w,h,t,progress){const phase=Math.min(3,Math.floor(progress/8)),beat=1+amplitude*.12,scale=Math.min(w,h)*.32;const cx=w*.5,cy=h*.52;c.save();c.globalAlpha=.65;
 if(phase===0){for(let j=0;j<9;j++){const pts=[];for(let x=0;x<=w;x+=4){const env=Math.exp(-(((x-w*.5)/(w*.4))**2));pts.push([x,h*.23+j*h*.067+Math.sin(x*.023-t*(1+j*.07)+j*.5)*25*env*beat]);}line(c,pts,j%2?'#d5b6e455':'#a2dcc650',.9);}for(let j=0;j<6;j++){const r=scale*(.3+j*.22),pts=[];for(let a=0;a<6.3;a+=.025)pts.push([cx+Math.cos(a)*r,cy+Math.sin(a*3+t*.4)*r*.5]);line(c,pts,'#ccb6f030');}}
 if(phase===1){for(let j=0;j<6;j++){c.save();c.translate(cx,cy);c.rotate(j*.5+t*.025);c.beginPath();c.ellipse(0,0,scale*(.5+j*.19),scale*(.18+j*.05),0,0,Math.PI*2);c.strokeStyle=j%2?'#f1afba60':'#c7b1f355';c.stroke();const a=t*(.25+j*.1)+j;circle(c,Math.cos(a)*scale*(.5+j*.19),Math.sin(a)*scale*(.18+j*.05),4,'#f8dfb6');c.restore();}for(let j=0;j<12;j++){const pts=[];for(let i=0;i<41;i++){const x=(i/40-.5)*w*.9,y=(j/11-.5)*h*.75,d=Math.hypot(x,y);pts.push([cx+x,cy+y+70*Math.exp(-d*d/40000)]);}line(c,pts,'#c7b1f319');}}
 if(phase===2){let x=.1,y=0,z=0;const pts=[];for(let i=0;i<2300;i++){const dt=.008,dx=10*(y-x),dy=x*(28-z)-y,dz=x*y-8/3*z;x+=dx*dt;y+=dy*dt;z+=dz*dt;if(i>100){const a=t*.08;pts.push([cx+(x*Math.cos(a)+y*Math.sin(a))*scale/24,cy+(z-25)*scale/30]);}}line(c,pts,'#c7b1f36b',.7);const pts2=[];for(let a=0;a<=Math.PI*8;a+=.03)pts2.push([cx+Math.sin(a*3+t*.2)*scale*1.1,cy+Math.sin(a*2)*scale*.7]);line(c,pts2,'#f1afba2b',.7);}
 if(phase===3)drawHeart(c,cx,cy,scale*.95*beat,t,.9);
 const formulas=['iℏ ∂ψ/∂t = Ĥψ','∇ · E = ρ/ε₀','E = hf','F = ma','Gμν + Λgμν = 8πG Tμν / c⁴','x = 16 sin³(t)','∂²u/∂t² = c²∇²u','eⁱπ + 1 = 0','Δx Δp ≥ ℏ/2','∮ B · dl = μ₀I'];c.font=`italic ${w<600?12:17}px Georgia`;for(let i=0;i<formulas.length;i++){const x=(.06+hash(i*3)*.78)*w,y=(.14+hash(i*7)*.76)*h;c.fillStyle=i%2?'#d9b3bd75':'#c7b1f365';c.fillText(formulas[i],x,y+Math.sin(t*.2+i)*7);}c.restore();}
function updateIntro(dt){introTime+=dt;const scenes=[['01 / THE LANGUAGE OF THE UNIVERSE','IN THE BEGINNING, THERE WAS CURIOSITY.','A universe of possibilities.','And somehow, out of all of them…'],['02 / EVERYTHING IS CONNECTED','GRAVITY. LIGHT. A MILLION LITTLE MIRACLES.','Everything has a beautiful explanation.','Some things are simply worth falling for.'],['03 / A BEAUTIFUL KIND OF CHAOS','SOME PEOPLE SEE EQUATIONS.','You see a world worth understanding.','And a world worth sharing.'],['04 / THE MOST IMPORTANT CONSTANT','OUT OF ALL THE STARS IN THE SKY…','This little universe is for you, Faeze.','Its brightest part was always you.']];const s=scenes[Math.min(3,Math.floor(introTime/8))];$('scene-label').textContent=s[0];$('intro-kicker').textContent=s[1];$('intro-title').textContent=s[2];$('intro-sub').textContent=s[3];$('intro-progress').style.width=`${Math.min(100,introTime/32*100)}%`;if(introTime>=32)show('flower');}
function tick(now){const realDT=Math.max(0,(now-last)/1000),dt=Math.min(realDT,.25);last=now;if(!document.hidden){elapsed+=dt;if(analyser&&!music.paused){analyser.getByteFrequencyData(audioData);amplitude=audioData.reduce((a,b)=>a+b,0)/audioData.length/255;}else amplitude=0;if(screen==='intro')updateIntro(realDT);if(screen!=='lab')drawSky();if(screen==='lab')lab.update(dt,calm);}requestAnimationFrame(tick);}requestAnimationFrame(tick);
